/* LTTPR / PHY repeater helpers from newer drm/display/drm_dp.h */
#ifndef AMDGPU_DP_PHY_LTTPR_COMPAT
#define AMDGPU_DP_PHY_LTTPR_COMPAT
enum drm_dp_phy {
	DP_PHY_DPRX,
	DP_PHY_LTTPR1,
	DP_PHY_LTTPR2,
	DP_PHY_LTTPR3,
	DP_PHY_LTTPR4,
	DP_PHY_LTTPR5,
	DP_PHY_LTTPR6,
	DP_PHY_LTTPR7,
	DP_PHY_LTTPR8,
	DP_MAX_LTTPR_COUNT = DP_PHY_LTTPR8,
};
#endif

#ifndef DP_PHY_LTTPR
#define DP_PHY_LTTPR(i)					(DP_PHY_LTTPR1 + (i))
#endif
#ifndef __DP_LTTPR1_BASE
#define __DP_LTTPR1_BASE				0xf0010
#endif
#ifndef __DP_LTTPR2_BASE
#define __DP_LTTPR2_BASE				0xf0060
#endif
#ifndef DP_LTTPR_BASE
#define DP_LTTPR_BASE(dp_phy) \
	(__DP_LTTPR1_BASE + (__DP_LTTPR2_BASE - __DP_LTTPR1_BASE) * \
		((dp_phy) - DP_PHY_LTTPR1))
#endif
#ifndef DP_LTTPR_REG
#define DP_LTTPR_REG(dp_phy, lttpr1_reg) \
	(DP_LTTPR_BASE(dp_phy) - DP_LTTPR_BASE(DP_PHY_LTTPR1) + (lttpr1_reg))
#endif
#ifndef DP_TRAINING_PATTERN_SET_PHY_REPEATER
#define DP_TRAINING_PATTERN_SET_PHY_REPEATER(dp_phy) \
	DP_LTTPR_REG(dp_phy, DP_TRAINING_PATTERN_SET_PHY_REPEATER1)
#endif
#ifndef __DP_FEC1_BASE
#define __DP_FEC1_BASE					0xf0290
#endif
#ifndef __DP_FEC2_BASE
#define __DP_FEC2_BASE					0xf0298
#endif
#ifndef DP_FEC_BASE
#define DP_FEC_BASE(dp_phy) \
	(__DP_FEC1_BASE + ((__DP_FEC2_BASE - __DP_FEC1_BASE) * \
			   ((dp_phy) - DP_PHY_LTTPR1)))
#endif
#ifndef DP_FEC_REG
#define DP_FEC_REG(dp_phy, fec1_reg) \
	(DP_FEC_BASE(dp_phy) - DP_FEC_BASE(DP_PHY_LTTPR1) + fec1_reg)
#endif
#ifndef DP_FEC_STATUS_PHY_REPEATER
#define DP_FEC_STATUS_PHY_REPEATER(dp_phy) \
	DP_FEC_REG(dp_phy, DP_FEC_STATUS_PHY_REPEATER1)
#endif
#ifndef DP_LTTPR_MAX_ADD
#define DP_LTTPR_MAX_ADD				0xf02ff
#endif
#ifndef DP_DPCD_MAX_ADD
#define DP_DPCD_MAX_ADD					0xfffff
#endif

#endif /* _AMDGPU_DP_REGS_COMPAT_H_ */
